script:
set s to (current date)
set year of s to {start_y}
set month of s to {start_mo}
set day of s to {start_d}
set time of s to ({start_h} * hours) + ({start_mi} * minutes)
set e to s + ({minutes} * minutes)
tell application "Calendar"
  tell calendar 1
    make new event with properties {summary:"{title}", start date:s, end date:e}
  end tell
end tell
return "created"

tell application "Mail"
  set m to make new outgoing message with properties {subject:"{subject}", content:"{body}", visible:false}
  tell m to make new to recipient at end of to recipients with properties {address:"{to}"}
  send m
end tell
return "sent"

set d to (current date)
set year of d to {due_y}
set month of d to {due_mo}
set day of d to {due_d}
set time of d to ({due_h} * hours) + ({due_mi} * minutes)
tell application "Reminders"
  make new reminder with properties {name:"{title}", due date:d}
end tell
return "created"
